import test from 'node:test';
import assert from 'node:assert/strict';
import {Chess} from '../../../../lib/chess.js';
import {openResearchData} from '../../../data-policy.mjs';
import {boardFen} from '../../FRIEND-shared/lib.mjs';
import {fixtures} from './fixtures.mjs';
import {savedPanels,withSavedPanel} from './saved-panels.mjs';
import {explainMove} from './minority.mjs';
import {checkWitness} from './check-witness.mjs';
import {explainMove as parent} from '../../E148-causal-center-instability/code/center.mjs';
await openResearchData(['D001'],{purpose:'test'});const saved=await savedPanels(),f=fixtures[0],input=withSavedPanel(f,saved),result=explainMove(input),cf=fixtures[2],cr=explainMove(withSavedPanel(cf,saved)),own=r=>r.events.filter(e=>e.evidence?.experiment==='E149');
for(const fixture of fixtures)test(fixture.id,()=>{const r=explainMove(withSavedPanel(fixture,saved));assert.deepEqual(own(r).map(e=>e.id),fixture.expected);assert.deepEqual(r.events.filter(e=>e.evidence?.experiment!=='E149'),parent(fixture).events);if(r.minorityStructureAnalysis.witness)checkWitness(r.minorityStructureAnalysis.witness,r,fixture);});
test('disabled exactly parent',()=>{for(const minorityStructureTags of [undefined,false]){const i={...f,minorityStructureTags,maxMinorityStructureNodes:null,minorityStructurePanel:null};assert.deepEqual(explainMove(i),parent(i));}});
test('strict controls',()=>{for(const minorityStructureTags of [null,1,'true'])assert.throws(()=>explainMove({...input,minorityStructureTags}));for(const maxMinorityStructureNodes of [null,-1,50001,0.5])assert.throws(()=>explainMove({...input,maxMinorityStructureNodes}));assert.throws(()=>explainMove({...input,minorityStructurePanel:null}));});
test('fresh and cached exact result and cost',()=>{assert.deepEqual(explainMove(f),result);assert.deepEqual(explainMove(cf),cr);});
test('exact and one-short atomic budget',()=>{const n=cr.minorityStructureAnalysis.nodes;for(const cached of [true,false]){const i=cached?withSavedPanel(cf,saved):cf;assert.equal(explainMove({...i,maxMinorityStructureNodes:n}).minorityStructureAnalysis.status,'proven');const j={...i,maxMinorityStructureNodes:n-1},r=explainMove(j);assert.equal(r.minorityStructureAnalysis.status,'exhausted');assert.equal(r.minorityStructureAnalysis.nodes,n);assert.equal(r.minorityStructureAnalysis.witness,null);assert.deepEqual(r.events,parent(j).events);assert.equal(r.comment,parent(j).comment);}});
test('generic panel bound to source and complete alternative inventory',()=>{const c=new Chess(f.fen);c.remove('c6');c.put({type:'p',color:'b'},'c7');const fen=c.fen(),i={...f,fen,history:{fen,moves:[]},move:'b4b5'},a=explainMove(i),b=explainMove({...i,move:'b4b5',minorityStructurePanel:a.minorityStructureAnalysis.witness.panel});assert.deepEqual(a,b);assert.ok(a.minorityStructureAnalysis.witness.panel.legal.length>1);});
test('previous contact does not become a new lever',()=>{const fen=boardFen({h1:'K',d1:'R',a4:'P',b5:'P',h8:'k',a7:'p',c6:'p',d5:'p'}),i={...f,fen,history:{fen,moves:[]},move:'b5b6'},r=explainMove(i);assert.deepEqual(own(r),[]);checkWitness(r.minorityStructureAnalysis.witness,r,i);});
test('already isolated target is exploitation but not newly created minority target',()=>{const start=boardFen({h1:'K',a1:'R',a4:'P',b4:'P',h8:'k',a6:'p',c6:'p',d5:'p'}),moves=['b4b5','c6b5','a4b5','h8h7'],c=new Chess(start);for(const m of moves)c.move(m);const i={...cf,fen:c.fen(),history:{fen:start,moves},move:'a1a6'},r=explainMove(i);assert.deepEqual(own(r).map(e=>e.id),['bounded-structural-exploitation']);assert.equal(r.minorityStructureAnalysis.witness.recorded,null);checkWitness(r.minorityStructureAnalysis.witness,r,i);});
test('equal initial groups cannot establish a minority plan',()=>{const start=fixtures[4].fen,moves=['b4b5','c6b5','a4b5','h8h7'],c=new Chess(start);for(const m of moves)c.move(m);const i={...cf,fen:c.fen(),history:{fen:start,moves}},r=explainMove(i);assert.deepEqual(own(r),[]);checkWitness(r.minorityStructureAnalysis.witness,r,i);});
test('terminal capture cannot establish nominal advantage',()=>{const fen=boardFen({h1:'K',c4:'B',h8:'k',b5:'p'}),i={...cf,fen,history:{fen,moves:[]},move:'c4b5'},r=explainMove(i),w=r.minorityStructureAnalysis.witness,row=w.panel.variants[0];assert.equal(row.captureLedger.afterFlags.insufficient,true);assert.deepEqual(row.legal,[]);assert.deepEqual(row.captureLedger.replies,[]);assert.deepEqual(own(r),[]);checkWitness(w,r,i);});
test('en passant contact uses removed pawn rather than landing square',()=>{const fen=boardFen({a1:'K',e2:'P',f2:'P',a8:'k',f4:'p',g6:'p',h7:'p'}),i={...f,fen,history:{fen,moves:[]},move:'e2e4'},r=explainMove(i),w=r.minorityStructureAnalysis.witness;assert.equal(w.lever.captures[0].enPassant,true);assert.equal(w.lever.captures[0].victim,'e4');assert.equal(w.lever.captures[0].to,'e3');assert.equal(w.panel.variants.length,2);checkWitness(w,r,i);});
test('longer history retained and irreversible move resets clock',()=>{const moves=['h1g1','h8g8','g1h1','g8h8'],c=new Chess(f.fen);for(const m of moves)c.move(m);const i={...f,fen:c.fen(),history:{fen:f.fen,moves}},r=explainMove(i);assert.deepEqual(own(r).map(e=>e.id),f.expected);checkWitness(r.minorityStructureAnalysis.witness,r,i);const fen=f.fen.replace(' 0 1',' 99 1'),j={...f,fen,history:{fen,moves:[]}},s=explainMove(j);assert.deepEqual(s.minorityStructureAnalysis.witness.panel.claimContexts,[]);assert.equal(new Chess(s.after).fen().split(' ')[4],'0');checkWitness(s.minorityStructureAnalysis.witness,s,j);});
for(const [name,mutate]of Object.entries({rootInventory:w=>w.panel.legal.pop(),variantInventory:w=>w.panel.variants.pop(),opponentInventory:w=>w.panel.variants[0].legal.pop(),captureInventory:w=>w.panel.variants[0].pawnCaptures.pop(),structure:w=>w.panel.beforeStructure.w.isolated=[],postStructure:w=>w.panel.variants[0].structure.b.isolated=[],history:w=>w.panel.history.moves=['h1g1'],cost:w=>w.panel.nodes--,claim:w=>w.panel.claimContexts=['invented'],lever:w=>w.lever.own=[],san:w=>w.san='fiction'}))test('independent lever mutation '+name,()=>{const r=structuredClone(result);mutate(r.minorityStructureAnalysis.witness);assert.throws(()=>checkWitness(r.minorityStructureAnalysis.witness,r,f));});
for(const [name,mutate]of Object.entries({replyInventory:w=>w.panel.variants[0].captureLedger.replies.pop(),gain:w=>w.panel.variants[0].captureLedger.replies[0].gain=8,baseline:w=>w.panel.variants[0].captureLedger.baseline++,terminal:w=>w.panel.variants[0].captureLedger.afterFlags.insufficient=true,health:w=>w.health.minimumGain++,target:w=>w.recorded.target='b7',sequence:w=>w.recorded.sequence.pop(),prefix:w=>w.recorded.prefix.moves=['h1g1'],initial:w=>w.recorded.initialStructure.b.isolated=['d5'],exchange:w=>w.recorded.exchangeStructure.b.isolated=[]}))test('independent structural mutation '+name,()=>{const r=structuredClone(cr);mutate(r.minorityStructureAnalysis.witness);assert.throws(()=>checkWitness(r.minorityStructureAnalysis.witness,r,cf));});
test('caller cannot admit altered raw panel',()=>{const i=structuredClone(withSavedPanel(cf,saved));i.minorityStructurePanel.variants[0].captureLedger.replies.pop();assert.throws(()=>explainMove(i));});
test('independent quality and label metadata',()=>{for(const mutate of [r=>own(r)[0].qualityClaim=true,r=>own(r)[0].text='Strategic victory',r=>r.events.pop(),r=>r.minorityStructureAnalysis.status='compared']){const r=structuredClone(cr);mutate(r);assert.throws(()=>checkWitness(r.minorityStructureAnalysis.witness,r,cf));}});
